const tabId = 480038496;
const res = await browserjs(tabId, () => {
  // Let's find any modal/backdrop/dialog elements
  const dialog = document.querySelector('[role="dialog"]') || document.querySelector('div[data-test-id="login-modal-default"]') || document.querySelector('div[aria-modal="true"]');
  const overlay = document.querySelector('div[data-test-id="full-page-signup-modal"]') || document.querySelector('.gestalt-overlay') || document.querySelector('div[style*="z-index"]');
  // Also check if body has overflow hidden
  document.body.style.overflow = 'auto';

  // Let's remove the modal and its backdrop if found
  let removed = [];
  document.querySelectorAll('[role="dialog"], div[data-test-id*="modal"], div[data-test-id*="signup"], div[data-test-id*="login"]').forEach(el => {
    // Make sure we only remove overlays, not the main content
    if (el.closest('main') === null && (el.getAttribute('role') === 'dialog' || el.innerText.includes('Welcome to Pinterest'))) {
      removed.push(el.className || el.tagName);
      // find overlay wrapper
      let p = el;
      while (p && p.parentElement && p.parentElement !== document.body && !p.parentElement.querySelector('main')) {
        p = p.parentElement;
      }
      p.remove();
    }
  });
  return { removed };
});
console.log("Removal result:", res);

const shot = await browser.screenshot({ tabId });
console.log("Screenshot after removal:", shot.image);

