const tabId = 480038496;
const res = await browserjs(tabId, () => {
  // Check for any backdrop or dark overlay
  const style = document.getElementById('hide-modal-style');
  if (style) {
    style.innerHTML += `
      div[data-test-id="backdrop"],
      div[style*="background-color: rgba(0, 0, 0"],
      div[style*="background-color: rgb(0 0 0 /"] {
        display: none !important;
      }
    `;
  }
  // Remove any backdrop elements directly
  document.querySelectorAll('div').forEach(el => {
    const bg = window.getComputedStyle(el).backgroundColor;
    if (bg.includes('rgba(0, 0, 0,') && window.getComputedStyle(el).position === 'fixed') {
      el.remove();
    }
  });
  return { done: true };
});
console.log(res);

const shot = await browser.screenshot({ tabId });
console.log("Screenshot after backdrop fix:", shot.image);

