const tabId = 480038377;
const results = await browserjs(tabId, () => {
  const items = [];
  // Look for image search result cards or links
  document.querySelectorAll('div[data-lpage], a[href*="imgurl"], div[jsname][data-ri]').forEach(el => {
    const img = el.querySelector('img');
    const a = el.closest('a') || el.querySelector('a');
    const text = el.innerText;
    items.push({
      text: text?.slice(0, 100),
      href: a?.href,
      imgSrc: img?.src?.slice(0, 100)
    });
  });
  // Also check general image result anchors
  const allAnchors = Array.from(document.querySelectorAll('a')).filter(a => a.href && (a.href.includes('imgres') || a.href.includes('google.com/url')));
  return {
    itemsCount: items.length,
    items: items.slice(0, 10),
    anchorCount: allAnchors.length,
    anchors: allAnchors.slice(0, 10).map(a => ({ text: a.innerText.slice(0, 80), href: a.href }))
  };
});
console.log("Image search results info:", results);

